public static void addTempAuthParam(ParserCreate parserCreate, String authType, 
                                         String authToken, String authPassword,
                                         String authInfo1, String authInfo2, String authInfo3,
                                         String authInfo4, String authInfo5) {
        if (StringUtils.isBlank(authType) && StringUtils.isBlank(authToken)) {
            // 没有提供临时认证参数，使用后台配置
            addParam(parserCreate);
            return;
        }

        // 先添加代理配置和域名配置
        LocalMap<Object, Object> localMap = VertxHolder.getVertxInstance().sharedData()
                .getLocalMap(ConfigConstant.LOCAL);
        String type = parserCreate.getShareLinkInfo().getType();

        if (localMap.containsKey(ConfigConstant.PROXY)) {
            JsonObject proxy = (JsonObject) localMap.get(ConfigConstant.PROXY);
            if (proxy.containsKey(type)) {
                parserCreate.getShareLinkInfo().getOtherParam().put(ConfigConstant.PROXY, proxy.getJsonObject(type));
            }
        }

        String linkPrefix = SharedDataUtil.getJsonConfig("server").getString("domainName");
        if (StringUtils.isBlank(linkPrefix)) {
            linkPrefix = parserCreate.getShareLinkInfo().getOtherParam()
                    .getOrDefault("_requestOrigin", "").toString();
        }
        if (StringUtils.isNotBlank(linkPrefix)) {
            parserCreate.getShareLinkInfo().getOtherParam().put("domainName", linkPrefix);
        }

        // 构建临时认证信息
        MultiMap tempAuth = MultiMap.caseInsensitiveMultiMap();

        if (StringUtils.isNotBlank(authType)) {
            tempAuth.set("authType", authType.trim());
        }

        String authTypeValue = authType != null ? authType : "";
        switch (authTypeValue.toLowerCase()) {
            case "accesstoken":
            case "authorization":
                if (StringUtils.isNotBlank(authToken)) {
                    tempAuth.set("token", authToken.trim());
                }
                break;

            case "cookie":
                // cookie 类型需要同时设置 token 和 cookie 字段
                // QkTool/UcTool 等从 auths.get("cookie") 获取 cookie 值
                if (StringUtils.isNotBlank(authToken)) {
                    tempAuth.set("token", authToken.trim());
                    tempAuth.set("cookie", authToken.trim());
                }
                break;

            case "password":
            case "username_password":
                if (StringUtils.isNotBlank(authToken)) {
                    tempAuth.set("username", authToken.trim());
                    tempAuth.set("token", authToken.trim()); // 兼容旧的解析器
                }
                if (StringUtils.isNotBlank(authPassword)) {
                    tempAuth.set("password", authPassword.trim());
                }
                break;

            case "custom":
                // 自定义认证支持多个扩展字段
                if (StringUtils.isNotBlank(authToken)) {
                    tempAuth.set("token", authToken.trim());
                }
                if (StringUtils.isNotBlank(authInfo1)) {
                    parseAndSetAuthInfo(tempAuth, authInfo1);
                }
                if (StringUtils.isNotBlank(authInfo2)) {
                    parseAndSetAuthInfo(tempAuth, authInfo2);
                }
                if (StringUtils.isNotBlank(authInfo3)) {
                    parseAndSetAuthInfo(tempAuth, authInfo3);
                }
                if (StringUtils.isNotBlank(authInfo4)) {
                    parseAndSetAuthInfo(tempAuth, authInfo4);
                }
                if (StringUtils.isNotBlank(authInfo5)) {
                    parseAndSetAuthInfo(tempAuth, authInfo5);
                }
                break;

            default:
                // 默认处理：将authToken作为token
                if (StringUtils.isNotBlank(authToken)) {
                    tempAuth.set("token", authToken.trim());
                }
                break;
        }

        // 设置临时认证信息（覆盖后台配置）
        if (!tempAuth.isEmpty()) {
            parserCreate.getShareLinkInfo().getOtherParam().put(ConfigConstant.AUTHS, tempAuth);
            // 设置标记表示已添加临时认证
            parserCreate.getShareLinkInfo().getOtherParam().put("__TEMP_AUTH_ADDED", true);
            log.debug("已添加临时认证参数: diskType={}, authType={}", type, authType);
        } else {
            // 如果没有有效的临时认证参数，回退到使用后台配置
            if (localMap.containsKey(ConfigConstant.AUTHS)) {
                JsonObject auths = (JsonObject) localMap.get(ConfigConstant.AUTHS);
                if (auths.containsKey(type)) {
                    MultiMap entries = MultiMap.caseInsensitiveMultiMap();
                    JsonObject jsonObject = auths.getJsonObject(type);
                    if (jsonObject != null) {
                        jsonObject.forEach(entity -> {
                            if (entity == null || entity.getValue() == null) {
                                return;
                            }
                            if (StringUtils.isEmpty(entity.getKey()) || StringUtils.isEmpty(entity.getValue().toString())) {
                                return;
                            }
                            entries.set(StringUtils.trim(entity.getKey()), StringUtils.trim(entity.getValue().toString()));
                        });
                    }
                    parserCreate.getShareLinkInfo().getOtherParam().put(ConfigConstant.AUTHS, entries);
                }
            }
        }
    }

@RouteMapping(value = "/test", method = RouteMethod.POST)
    public Future<JsonObject> test(RoutingContext ctx) {
        // 检查是否启用
        if (!checkEnabled()) {
            return Future.succeededFuture(JsonResult.error("演练场功能已禁用").toJsonObject());
        }

        // 权限检查
        if (!checkAuth(ctx)) {
            return Future.succeededFuture(JsonResult.error("未授权访问").toJsonObject());
        }

        Promise<JsonObject> promise = Promise.promise();

        try {
            JsonObject body = ctx.body().asJsonObject();
            String jsCode = body.getString("jsCode");
            String shareUrl = body.getString("shareUrl");
            String pwd = body.getString("pwd");
            String method = body.getString("method", "parse");

            // 参数验证
            if (StringUtils.isBlank(jsCode)) {
                promise.complete(JsonObject.mapFrom(PlaygroundTestResp.builder()
                        .success(false)
                        .error("JavaScript代码不能为空")
                        .build()));
                return promise.future();
            }

            // 代码长度验证
            if (jsCode.length() > MAX_CODE_LENGTH) {
                promise.complete(JsonObject.mapFrom(PlaygroundTestResp.builder()
                        .success(false)
                        .error("代码长度超过限制（最大128KB），当前长度: " + jsCode.length() + " 字节")
                        .build()));
                return promise.future();
            }

            if (StringUtils.isBlank(shareUrl)) {
                promise.complete(JsonObject.mapFrom(PlaygroundTestResp.builder()
                        .success(false)
                        .error("分享链接不能为空")
                        .build()));
                return promise.future();
            }

            // ===== 新增：验证URL匹配 =====
            try {
                var config = JsScriptMetadataParser.parseScript(jsCode);
                Pattern matchPattern = config.getMatchPattern();

                if (matchPattern != null) {
                    Matcher matcher = matchPattern.matcher(shareUrl);
                    if (!matcher.matches()) {
                        promise.complete(JsonObject.mapFrom(PlaygroundTestResp.builder()
                                .success(false)
                                .error("分享链接与脚本的@match规则不匹配\n" +
                                       "规则: " + matchPattern.pattern() + "\n" +
                                       "链接: " + shareUrl)
                                .build()));
                        return promise.future();
                    }
                }
            } catch (IllegalArgumentException e) {
                promise.complete(JsonObject.mapFrom(PlaygroundTestResp.builder()
                        .success(false)
                        .error("解析脚本元数据失败: " + e.getMessage())
                        .build()));
                return promise.future();
            }
            // ===== 验证结束 =====

            // 验证方法类型
            if (!"parse".equals(method) && !"parseFileList".equals(method) && !"parseById".equals(method)) {
                promise.complete(JsonObject.mapFrom(PlaygroundTestResp.builder()
                        .success(false)
                        .error("方法类型无效，必须是 parse、parseFileList 或 parseById")
                        .build()));
                return promise.future();
            }

            long startTime = System.currentTimeMillis();

            try {
                // 创建ShareLinkInfo
                ParserCreate parserCreate = ParserCreate.fromShareUrl(shareUrl);
                if (StringUtils.isNotBlank(pwd)) {
                    parserCreate.setShareLinkInfoPwd(pwd);
                }
                ShareLinkInfo shareLinkInfo = parserCreate.getShareLinkInfo();

                // 创建演练场执行器
                final JsPlaygroundExecutor executor = new JsPlaygroundExecutor(shareLinkInfo, jsCode);

                // 根据方法类型选择执行，并异步处理结果
                Future<Object> executionFuture;
                try {
                    switch (method) {
                        case "parse":
                            executionFuture = executor.executeParseAsync().map(r -> (Object) r);
                            break;
                        case "parseFileList":
                            executionFuture = executor.executeParseFileListAsync().map(r -> (Object) r);
                            break;
                        case "parseById":
                            executionFuture = executor.executeParseByIdAsync().map(r -> (Object) r);
                            break;
                        default:
                            executor.close();
                            promise.fail(new IllegalArgumentException("未知的方法类型: " + method));
                            return promise.future();
                    }
                } catch (Exception ex) {
                    // 同步异常路径：executor 已创建但 Future 未注册，需要手动关闭
                    executor.close();
                    throw ex;
                }

                // 异步处理执行结果，finally 中统一释放 executor，避免响应构建异常导致资源泄漏
                executionFuture.onComplete(ar -> {
                    try {
                        long executionTime = System.currentTimeMillis() - startTime;
                        List<JsPlaygroundLogger.LogEntry> logEntries = executor.getLogs();
                        List<PlaygroundTestResp.LogEntry> respLogs = logEntries.stream()
                                .map(entry -> PlaygroundTestResp.LogEntry.builder()
                                        .level(entry.getLevel())
                                        .message(entry.getMessage())
                                        .timestamp(entry.getTimestamp())
                                        .source(entry.getSource())
                                        .build())
                                .collect(Collectors.toList());

                        if (ar.succeeded()) {
                            Object result = ar.result();
                            log.debug("执行成功，结果类型: {}, 结果摘要: {}",
                                    result != null ? result.getClass().getSimpleName() : "null",
                                    summarizeResult(result));

                            PlaygroundTestResp response = PlaygroundTestResp.builder()
                                    .success(true)
                                    .result(result)
                                    .logs(respLogs)
                                    .executionTime(executionTime)
                                    .build();

                            log.debug("测试成功响应: success=true, logCount={}", respLogs.size());
                            promise.complete(JsonObject.mapFrom(response));
                        } else {
                            Throwable e = ar.cause();
                            String errorMessage = e == null ? "执行失败" : e.getMessage();
                            log.error("演练场执行失败", e);

                            PlaygroundTestResp response = PlaygroundTestResp.builder()
                                    .success(false)
                                    .error(errorMessage)
                                    .executionTime(executionTime)
                                    .logs(respLogs)
                                    .build();

                            promise.complete(JsonObject.mapFrom(response));
                        }
                    } catch (Exception e) {
                        log.error("构建演练场响应失败", e);
                        promise.tryComplete(JsonObject.mapFrom(PlaygroundTestResp.builder()
                                .success(false)
                                .error("构建响应失败: " + e.getMessage())
                                .build()));
                    } finally {
                        executor.close();
                    }
                });

            } catch (Exception e) {
                long executionTime = System.currentTimeMillis() - startTime;
                String errorMessage = e.getMessage();

                log.error("演练场初始化失败", e);

                PlaygroundTestResp response = PlaygroundTestResp.builder()
                        .success(false)
                        .error(errorMessage)
                        .executionTime(executionTime)
                        .logs(new ArrayList<>())
                        .build();

                promise.complete(JsonObject.mapFrom(response));
            }
        } catch (Exception e) {
            log.error("解析请求参数失败", e);
            promise.complete(JsonObject.mapFrom(PlaygroundTestResp.builder()
                    .success(false)
                    .error("解析请求参数失败")
                    .build()));
        }

        return promise.future();
    }

@Override
    public Future<String> parse() {
        String pwdId = shareLinkInfo.getShareKey();
        String passcode = shareLinkInfo.getSharePassword();
        if (passcode == null) {
            passcode = "";
        }

        log.debug("开始解析夸克网盘分享，pwd_id: {}, passcode: {}", pwdId, passcode.isEmpty() ? "无" : "有");

        // 第一步：获取分享 token
        JsonObject tokenRequest = new JsonObject()
                .put("pwd_id", pwdId)
                .put("passcode", passcode);

        client.postAbs(TOKEN_URL)
                .addQueryParam("pr", "ucpro")
                .addQueryParam("fr", "pc")
                .putHeaders(header)
                .sendJsonObject(tokenRequest)
                .onSuccess(res -> {
                    log.debug("第一阶段响应: {}", res.bodyAsString());
                    JsonObject resJson = asJson(res);

                    if (resJson.getInteger("code") != 0) {
                        fail(TOKEN_URL + " 返回异常: " + resJson);
                        return;
                    }

                    String stoken = resJson.getJsonObject("data").getString("stoken");
                    if (stoken == null || stoken.isEmpty()) {
                        fail("无法获取分享 token，可能的原因：1. Cookie 已过期 2. 分享链接已失效 3. 需要提取码但未提供");
                        return;
                    }

                    log.debug("成功获取 stoken: {}", stoken);

                    // 第二步：获取文件列表
                    client.getAbs(DETAIL_URL)
                            .addQueryParam("pr", "ucpro")
                            .addQueryParam("fr", "pc")
                            .addQueryParam("pwd_id", pwdId)
                            .addQueryParam("stoken", stoken)
                            .addQueryParam("pdir_fid", "0")
                            .addQueryParam("force", "0")
                            .addQueryParam("_page", "1")
                            .addQueryParam("_size", "50")
                            .addQueryParam("_fetch_banner", "1")
                            .addQueryParam("_fetch_share", "1")
                            .addQueryParam("_fetch_total", "1")
                            .addQueryParam("_sort", "file_type:asc,updated_at:desc")
                            .putHeaders(header)
                            .send()
                            .onSuccess(res2 -> {
                                log.debug("第二阶段响应: {}", res2.bodyAsString());
                                JsonObject resJson2 = asJson(res2);

                                if (resJson2.getInteger("code") != 0) {
                                    fail(DETAIL_URL + " 返回异常: " + resJson2);
                                    return;
                                }

                                JsonArray fileList = resJson2.getJsonObject("data").getJsonArray("list");
                                if (fileList == null || fileList.isEmpty()) {
                                    fail("未找到文件");
                                    return;
                                }

                                // 过滤出文件（排除文件夹）
                                List<JsonObject> files = new ArrayList<>();
                                for (int i = 0; i < fileList.size(); i++) {
                                    JsonObject item = fileList.getJsonObject(i);
                                    // 判断是否为文件：file=true 或 obj_category 不为空
                                    if (item.getBoolean("file", false) || 
                                        (item.getString("obj_category") != null && !item.getString("obj_category").isEmpty())) {
                                        files.add(item);
                                    }
                                }

                                if (files.isEmpty()) {
                                    fail("没有可下载的文件（可能都是文件夹）");
                                    return;
                                }

                                log.debug("找到 {} 个文件", files.size());

                                // 提取第一个文件的信息并保存到 otherParam
                                try {
                                    JsonObject firstFile = files.get(0);
                                    FileInfo fileInfo = new FileInfo();
                                    fileInfo.setFileId(firstFile.getString("fid"))
                                            .setFileName(firstFile.getString("file_name"))
                                            .setSize(firstFile.getLong("size", 0L))
                                            .setSizeStr(FileSizeConverter.convertToReadableSize(firstFile.getLong("size", 0L)))
                                            .setFileType(firstFile.getBoolean("file", true) ? "file" : "folder")
                                            .setCreateTime(formatEpochMs(firstFile.getLong("updated_at", 0L)))
                                            .setUpdateTime(formatEpochMs(firstFile.getLong("updated_at", 0L)))
                                            .setPanType(shareLinkInfo.getType());

                                    // 保存到 otherParam，供 CacheServiceImpl 使用
                                    shareLinkInfo.getOtherParam().put("fileInfo", fileInfo);
                                    log.debug("夸克提取文件信息: {}", fileInfo.getFileName());
                                } catch (Exception e) {
                                    log.warn("夸克提取文件信息失败，继续解析: {}", e.getMessage());
                                }

                                // 提取文件ID列表
                                List<String> fileIds = new ArrayList<>();
                                for (JsonObject file : files) {
                                    String fid = file.getString("fid");
                                    if (fid != null && !fid.isEmpty()) {
                                        fileIds.add(fid);
                                    }
                                }

                                if (fileIds.isEmpty()) {
                                    fail("无法提取文件ID");
                                    return;
                                }

                                // 第三步：解析下载链接（先直链，必要时才转存）
                                JsonObject firstFileForDownload = files.get(0);
                                String firstFid = firstFileForDownload.getString("fid");
                                String firstShareFidToken = firstFileForDownload.getString("share_fid_token");

                                resolveDownloadUrl(firstFid, pwdId, stoken, firstShareFidToken)
                                        .onSuccess(downloadUrl -> completeWithMeta(downloadUrl, buildDownloadHeaders(null)))
                                        .onFailure(handleFail("获取下载链接"));

                            }).onFailure(handleFail(DETAIL_URL));
                })
                .onFailure(handleFail(TOKEN_URL));

        return promise.future();
    }

